<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST')respond(405,'Method not allowed.');requireCsrf();$user=requireUser();if(!empty($_POST['website']))respond(200,'Thanks.',true);$last=(int)($_SESSION['last_submit']??0);if($last&&time()-$last<45)respond(429,'Please wait before submitting another vehicle.');
$clean=static fn(string $k,int $m):string=>mb_substr(trim((string)($_POST[$k]??'')),0,$m);$d=['vehicle'=>$clean('vehicle',100),'year'=>$clean('year',4),'mileage'=>preg_replace('/\D+/','',$clean('mileage',12))??'','condition'=>$clean('condition',1000)];$max=(int)date('Y')+1;$bad=[];if(mb_strlen($d['vehicle'])<2)$bad[]='vehicle';if(!preg_match('/^\d{4}$/',$d['year'])||(int)$d['year']<1900||(int)$d['year']>$max)$bad[]='year';if($d['mileage']===''||(int)$d['mileage']>2000000)$bad[]='mileage';if(mb_strlen($d['condition'])<10)$bad[]='condition';if($bad)respond(422,'Please check: '.implode(', ',$bad).'.');
$ip=$_SERVER['REMOTE_ADDR']??'unknown';$hash=hash_hmac('sha256',$ip,(string)($config['app_secret']??'change-me'));$created=gmdate('c');try{$s=db()->prepare('INSERT INTO vehicle_requests(created_at,user_id,vehicle,year,mileage,condition,ip_hash) VALUES(?,?,?,?,?,?,?)');$s->execute([$created,$user['id'],$d['vehicle'],(int)$d['year'],(int)$d['mileage'],$d['condition'],$hash]);}catch(Throwable $e){error_log($e->getMessage());respond(500,'We could not save the vehicle.');}
$to=(string)($config['recipient_email']??'');$site=(string)($config['site_name']??'Auto Cash');$from=(string)($config['from_email']??'no-reply@localhost');$subject='New authenticated lead: '.$d['year'].' '.$d['vehicle'];$body="New cash-offer request\n\nSeller: {$user['name']}\nPhone: {$user['phone']}\nEmail: {$user['email']}\nVehicle: {$d['year']} {$d['vehicle']}\nMileage: {$d['mileage']} mi\nCondition: {$d['condition']}\nSubmitted: {$created}\n";$headers=['From: '.$site.' <'.$from.'>','Content-Type: text/plain; charset=UTF-8'];$sent=$to&&filter_var($to,FILTER_VALIDATE_EMAIL)&&@mail($to,$subject,$body,implode("\r\n",$headers));if(!$sent)error_log('Lead saved but email delivery failed: '.$created);
if(!empty($config['google_sheets_webhook'])){$payload=json_encode(array_merge($d,['created_at'=>$created,'name'=>$user['name'],'email'=>$user['email'],'phone'=>$user['phone']]));$opts=['http'=>['method'=>'POST','header'=>"Content-Type: application/json\r\n",'content'=>$payload,'timeout'=>3,'ignore_errors'=>true]];@file_get_contents((string)$config['google_sheets_webhook'],false,stream_context_create($opts));}
$_SESSION['last_submit']=time();$_SESSION['csrf']=bin2hex(random_bytes(32));respond(200,'Vehicle received.',true,['csrf'=>$_SESSION['csrf']]);
